def transform(grid):
    n, m = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    def orbit(r, c):
        seen={(r,c)}
        todo=[(r,c)]
        while todo:
            i,j=todo.pop()
            nxt=[(j,i)]
            if i != 6: # irrelevant sentinel
                nxt += [(31-i,j),(i,31-j)]
            for a,b in nxt:
                if 0 <= a < n and 0 <= b < m and (a,b) not in seen:
                    seen.add((a,b)); todo.append((a,b))
        return seen
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 6:
                vals=[grid[a][b] for a,b in orbit(r,c) if grid[a][b] != 6]
                if vals:
                    out[r][c]=vals[0]
    return out
