def transform(grid):
    """Restore the grid's main-diagonal symmetry through the 6 mask."""
    out = [row[:] for row in grid]
    n, m = len(grid), len(grid[0])
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 6:
                v = grid[c][r]
                # In a symmetric overlap the source and counterpart are both masked.
                out[r][c] = 5 if v == 6 else v
    return out
